442022ae-316e-4b61-8d21-5f87c5bba718.script:
"var langs = ['en','th','ja'];
if (callbacks.isEmpty()) {
  callbacksBuilder.nameCallback('City');
  callbacksBuilder.choiceCallback('Preferred language', langs, 0, false);
} else {
  var city = String(callbacks.getNameCallbacks().get(0));
  var lang = langs[callbacks.getChoiceCallbacks().get(0)[0]];
  nodeState.mergeShared({objectAttributes: {city: city, frUnindexedString1: lang}});
  action.goTo('next');
}"

5f256a5e-48b3-4ff9-a2bb-b1db29781aa8.script:
"if (callbacks.isEmpty()) {
  var words = ['amber','falcon','river','cobalt','meadow'];
  var w = words[Math.floor(Math.random() * words.length)];
  nodeState.putShared('demoExpected', w);
  callbacksBuilder.textOutputCallback(0, 'Phrase challenge: your word is ' + w);
  callbacksBuilder.nameCallback('Type the word shown above');
} else {
  var ok = String(callbacks.getNameCallbacks().get(0)).trim() === String(nodeState.get('demoExpected'));
  action.goTo(ok ? 'pass' : 'fail');
}"

