3ea28c10-b6ff-49ce-bd4c-96ccab383866.script:
"var choices = ['web','mobile','partner'];
if (callbacks.isEmpty()) {
  callbacksBuilder.textOutputCallback(0, 'Welcome to the demo signup journey.');
  callbacksBuilder.choiceCallback('Which channel are you signing up from?', choices, 0, false);
} else {
  var picked = callbacks.getChoiceCallbacks().get(0)[0];
  nodeState.putShared('demoChannel', choices[picked]);
  action.goTo(choices[picked]);
}"

